const miniPopup=(title,name,buttons)=>`<div class="mini-popup-wrap"><div class="mini-popup"><button class="mini-close" id="close">×</button><h3>${esc(title)}</h3><p>${esc(name)}</p><div>${buttons}</div></div></div>`;
