function nvAlert(message){return new Promise(resolve=>{let d=document.createElement('div');d.className='nv-dialog-wrap';d.innerHTML=`<div class="nv-dialog"><h3>Nuestra Vida</h3><p>${esc(message)}</p><button class="primary">Aceptar</button></div>`;document.body.appendChild(d);d.querySelector('button').onclick=()=>{d.remove();resolve()}})}
function nvConfirm(message){return new Promise(resolve=>{let d=document.createElement('div');d.className='nv-dialog-wrap';d.innerHTML=`<div class="nv-dialog"><h3>Nuestra Vida</h3><p>${esc(message)}</p><div><button data-no>Cancelar</button><button class="primary" data-yes>Aceptar</button></div></div>`;document.body.appendChild(d);d.querySelector('[data-no]').onclick=()=>{d.remove();resolve(false)};d.querySelector('[data-yes]').onclick=()=>{d.remove();resolve(true)}})}
async function enableNotifications(){if(!('Notification'in window))return false;if(Notification.permission==='granted')return true;return(await Notification.requestPermission())==='granted'}
async function checkReminders(){if(!session||!('Notification'in window)||Notification.permission!=='granted')return;let now=Date.now();for(let e of events){if(!e.event_time||!+e.reminder_minutes)continue;let at=new Date(`${e.event_date}T${String(e.event_time).slice(0,5)}:00`).getTime()-+e.reminder_minutes*60000,key=`nv-reminder-${e.id}-${at}`;if(now>=at&&now<at+3600000&&!localStorage.getItem(key)){localStorage.setItem(key,'1');let r=await navigator.serviceWorker.ready;r.showNotification(`Recordatorio: ${e.title}`,{body:`${e.event_date} · ${String(e.event_time).slice(0,5)}`,icon:'icon-192.png',tag:`event-${e.id}`})}}}
