function bindShopping(){document.querySelectorAll('.history-product-direct').forEach(x=>x.onclick=async()=>{let row={family_id:profile.family_id,created_by:session.user.id,name:x.dataset.name,quantity:'1',category:x.dataset.store||'Otros',done:false},temp={...row,id:'temp-'+Date.now()+Math.random()};shopping.unshift(temp);render();let r=await sb.from('shopping_items').insert(row);if(r.error){shopping=shopping.filter(i=>i.id!==temp.id);render();return nvAlert(r.error.message)}await load();render()});document.querySelectorAll('.done').forEach(x=>x.onclick=e=>{e.preventDefault();e.stopPropagation();completeShoppingItem(x.dataset.id)})}
function bindHistorySorting(){let sel=$('#historySort'),grid=$('.history-grid.custom-sort');if(sel)sel.onchange=()=>{localStorage.setItem('nv-history-sort',sel.value);render()};if(!grid)return;let moving=null;grid.querySelectorAll('.history-product').forEach(card=>{card.draggable=true;card.addEventListener('dragstart',()=>{moving=card;card.classList.add('dragging')});card.addEventListener('dragover',e=>{e.preventDefault();if(!moving||moving===card)return;let r=card.getBoundingClientRect(),before=e.clientY<r.top+r.height/2||(Math.abs(e.clientY-(r.top+r.height/2))<r.height/2&&e.clientX<r.left+r.width/2);grid.insertBefore(moving,before?card:card.nextSibling)});card.addEventListener('dragend',()=>{card.classList.remove('dragging');moving=null;localStorage.setItem('nv-history-order',JSON.stringify([...grid.querySelectorAll('.history-product')].map(x=>x.dataset.historyName)))})});let touchCard=null;grid.querySelectorAll('.history-product').forEach(card=>{card.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;touchCard=card;card.setPointerCapture(e.pointerId);card.classList.add('dragging')});card.addEventListener('pointermove',e=>{if(!touchCard)return;let over=document.elementFromPoint(e.clientX,e.clientY)?.closest('.history-product');if(over&&over!==touchCard)grid.insertBefore(touchCard,e.clientX<over.getBoundingClientRect().left+over.offsetWidth/2?over:over.nextSibling)});card.addEventListener('pointerup',()=>{if(!touchCard)return;touchCard.classList.remove('dragging');touchCard=null;localStorage.setItem('nv-history-order',JSON.stringify([...grid.querySelectorAll('.history-product')].map(x=>x.dataset.historyName)))})})}
function bindNoteSorting(){let box=$('#notes-sortable');if(!box)return;let card=null,ghost=null,timer=null,dragging=false,suppress=false,sx=0,sy=0;const move=(x,y)=>{if(ghost){ghost.style.left=x+'px';ghost.style.top=y+'px'}},begin=(el,x,y)=>{card=el;dragging=true;suppress=true;el.classList.add('note-drag-source');let r=el.getBoundingClientRect();ghost=el.cloneNode(true);ghost.className=el.className+' note-drag-ghost';ghost.style.width=r.width+'px';ghost.style.height=r.height+'px';document.body.appendChild(ghost);move(x,y);navigator.vibrate?.(18)},reorder=(x,y)=>{let over=document.elementFromPoint(x,y)?.closest('[data-note-drag]');if(over&&over!==card){let r=over.getBoundingClientRect();box.insertBefore(card,y<r.top+r.height/2?over:over.nextSibling)}},cleanup=()=>{clearTimeout(timer);card?.classList.remove('note-drag-source');ghost?.remove();ghost=null;dragging=false},save=()=>localStorage.setItem('nv-note-order',JSON.stringify([...box.querySelectorAll('[data-note-drag]')].map(x=>x.dataset.id)));box.querySelectorAll('[data-note-drag]').forEach(el=>{el.addEventListener('touchstart',e=>{if(e.touches.length!==1||e.target.closest('.item-actions'))return;let t=e.touches[0];card=el;sx=t.clientX;sy=t.clientY;timer=setTimeout(()=>begin(el,t.clientX,t.clientY),240)},{passive:true});el.addEventListener('touchmove',e=>{if(!card)return;let t=e.touches[0];if(!dragging){if(Math.hypot(t.clientX-sx,t.clientY-sy)>10){clearTimeout(timer);card=null}return}e.preventDefault();move(t.clientX,t.clientY);reorder(t.clientX,t.clientY)},{passive:false});let end=e=>{clearTimeout(timer);if(dragging){e.preventDefault();e.stopPropagation();save();cleanup();setTimeout(()=>suppress=false,350)}card=null};el.addEventListener('touchend',end);el.addEventListener('touchcancel',()=>{cleanup();card=null});el.addEventListener('mousedown',e=>{if(e.button!==0||e.target.closest('.item-actions'))return;card=el;begin(el,e.clientX,e.clientY)})});document.addEventListener('mousemove',e=>{if(!dragging||!card)return;e.preventDefault();move(e.clientX,e.clientY);reorder(e.clientX,e.clientY)});document.addEventListener('mouseup',()=>{if(!dragging||!card)return;save();cleanup();card=null;setTimeout(()=>suppress=false,350)});box.addEventListener('click',e=>{if(suppress&&e.target.closest('[data-note-drag]')){e.preventDefault();e.stopImmediatePropagation()}},true)}
function bindTabSwipe(){let root=$('.app'),sx=0,sy=0,cx=0,cy=0,active=false;if(!root)return;const noSwipe=t=>t.closest('input,textarea,select,.modal,.drag-handle,[data-note-drag],[data-drag-kind],.history-grid.custom-sort,.meal-choice-backdrop,.girls-overlay');root.ontouchstart=e=>{if(e.touches.length!==1||noSwipe(e.target))return;let t=e.touches[0];sx=cx=t.clientX;sy=cy=t.clientY;active=true};root.ontouchmove=e=>{if(!active)return;let t=e.touches[0];cx=t.clientX;cy=t.clientY};root.ontouchend=e=>{if(!active)return;active=false;let t=e.changedTouches[0],dx=(t?.clientX??cx)-sx,dy=(t?.clientY??cy)-sy;if(Math.abs(dx)<35||Math.abs(dx)<Math.abs(dy)*.9)return;let buttons=[...document.querySelectorAll('nav button')].filter(b=>b.offsetParent!==null),index=buttons.findIndex(b=>b.classList.contains('active')),next=dx<0?index+1:index-1;if(index>=0&&next>=0&&next<buttons.length){buttons[next].click();scrollTo(0,0)}}}
function bindUser(){document.querySelectorAll('[data-girl-photo]').forEach(i=>i.onchange=()=>{let f=i.files?.[0];if(f)saveGirlPhoto(i.dataset.girlPhoto,f)});$('#custodyForm')?.addEventListener('submit',async e=>{e.preventDefault();let f=new FormData(e.target),next={enabled:f.get('enabled')==='on',child:'Adri',frequency:f.get('frequency')||'weekly',start:f.get('start'),startsWithMe:f.get('startsWithMe')==='yes',color:f.get('color')||'#7c6cf2'},r=await sb.auth.updateUser({data:{custody_shared:next}});if(r.error)return nvAlert(r.error.message);custody=next;session.user.user_metadata={...(session.user.user_metadata||{}),custody_shared:next};render();nvAlert('Custodia compartida actualizada.')});$('#profileForm')?.addEventListener('submit',async e=>{e.preventDefault();let name=new FormData(e.target).get('display_name').trim();if(!name)return nvAlert('Escribe un nombre visible.');let a=await sb.auth.updateUser({data:{display_name:name}});if(a.error)return nvAlert(a.error.message);let r=await sb.from('profiles').update({display_name:name}).eq('id',session.user.id);if(r.error)return nvAlert(r.error.message);profile.display_name=name;render();nvAlert('Nombre actualizado.')});$('#passwordForm')?.addEventListener('submit',async e=>{e.preventDefault();let r=await sb.auth.updateUser({password:new FormData(e.target).get('password')});nvAlert(r.error?.message||'Contraseña actualizada.')});$('#sendRecovery')?.addEventListener('click',async()=>{let r=await sb.auth.resetPasswordForEmail(session.user.email,{redirectTo:location.href});nvAlert(r.error?.message||'Correo de recuperación enviado.')});$('#updateApp')?.addEventListener('click',async()=>{let b=$('#updateApp');b.disabled=true;b.textContent='Limpiando caché…';try{let regs=await navigator.serviceWorker.getRegistrations();await Promise.all(regs.map(r=>r.unregister()));let keys=await caches.keys();await Promise.all(keys.map(k=>caches.delete(k)));let u=new URL('./',location.href);u.searchParams.set('actualizar',Date.now());location.replace(u.href)}catch(e){b.disabled=false;b.textContent='🔄 Actualizar aplicación';nvAlert('No se ha podido limpiar la caché.')}});$('#logout')?.addEventListener('click',()=>sb.auth.signOut())}
window.addEventListener('nv-menu-updated',async()=>{if(!session)return;await load();if(tab==='inicio'&&!document.querySelector('.menu-page'))render()});
